esc=lambda s:html.escape(s,quote=True)
def link(text,url,kind='button'):
    return f'<a class="{kind}" href="{esc(url)}">{text}</a>'
def photo(key,kind,alt):
    return f'<img src="{CDN}/pages/spa-beauty/{key}/assets/{kind}.webp" alt="{esc(alt)}" width="{1122 if kind=="hero" else 1536}" height="{1402 if kind=="hero" else 1024}" loading="{ "eager" if kind=="hero" else "lazy"}">'
def eyebrow(s):return f'<p class="eyebrow">{s}</p>'
def hero(key,title,lead,cta,alt,stats):
    return f'''<section class="hero"><div class="hero-copy"><a class="breadcrumb" href="{WEB}/spa-and-beauty-services-salem-wi">Spa &amp; Beauty / {esc(cta)}</a><img class="logo" src="{LOGO}" alt="Matrix Massage &amp; Bodywork" width="320" height="160">{eyebrow('MATRIX MASSAGE &amp; BODYWORK · SALEM, WI')}<h1>{title}</h1><p class="lead">{lead}</p><div class="actions">{link('BOOK '+cta.upper(),BOOK)}{link('Explore the experience','#experience','text-link')}</div><p class="hero-facts">{stats}</p></div><div class="hero-photo">{photo(key,'hero',alt)}<span class="image-caption">A moment, just for you.</span></div></section>'''
def intro(kicker,title,text):return f'<div class="section-intro">{eyebrow(kicker)}<h2>{title}</h2><p>{text}</p></div>'
def card(title,meta,desc,url=BOOK,label='VIEW &amp; BOOK'):
    return f'<article class="service-card">{eyebrow(meta)}<h3>{title}</h3><p>{desc}</p>{link(label,url,"text-link")}</article>'
def steps(items):return '<div class="steps">'+''.join(f'<article><span class="step-number">0{i+1}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate(items))+'</div>'
def faq(items):
    return '<section class="section faq"><div class="inner faq-grid"><div>'+eyebrow('GOOD TO KNOW')+'<h2>A few helpful details.</h2><p>Feel comfortable choosing your next visit.</p></div><div>'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div></div></section>'
def closing(title,text,cta):
    return f'<section class="close"><div class="close-inner">{eyebrow("MAKE ROOM FOR YOURSELF")}<h2>{title}</h2><p>{text}</p><div class="actions">{link(cta,BOOK,"button light")}{link("ALL SPA &amp; BEAUTY",WEB+"/spa-and-beauty-services-salem-wi","button outline")}</div><p class="location">24804 75th St · Salem, WI 53168 · Text 262-939-9325</p><p class="illustration">Treatment imagery is illustrative.</p></div></section>'

