def facials():
    b=hero('facials','Facials in Salem, WI','Personalized skincare for hydration, acne-prone skin, a smoother-looking complexion—and a little time to exhale.','a facial','Illustrative gentle facial massage with cream linens and deep teal accents.','Custom care · Circadia facials · Dermaplaning · Skin goals')
    b+='<nav class="jump" aria-label="Facial page sections">'+''.join(link(t,u,'') for t,u in [('The experience','#experience'),('Acne-prone skin','#acne-prone-skin'),('Facial menu','#facial-menu'),('Skin goals','#skin-goals')])+'</nav>'
    b+='<section class="section paper" id="experience"><div class="inner">'+intro('PERSONAL SKINCARE, RESTORATIVE TOUCH','Your skin. Your priorities.','Your Custom Facial starts with how your skin looks and feels today. At Matrix Massage &amp; Bodywork, professional skincare—including Circadia options—is selected around your goals, sensitivities and the appointment you choose.')+steps([('Tell us what matters','Dryness, breakouts, congestion, sensitivity or a special occasion: share your priorities and current routine.'),('Care, thoughtfully chosen','Cleansing, suitable exfoliation, masks, serums and hydration are selected for your skin and comfort.'),('Leave with a next step','Enjoy your refreshed finish and practical aftercare. Your provider can help you choose care between visits.')])+'</div></section>'
    b+='<section class="section sage" id="acne-prone-skin"><div class="inner split">'+photo('facials','support','Illustrative skincare consultation showing natural skin texture and mild blemishes.')+'<div class="split-copy">'+eyebrow('CLEAR + BALANCE')+'<h2>Facials for acne-prone skin in Salem, WI.</h2><p>Breakouts, clogged-looking pores and excess shine deserve thoughtful attention. A Custom Facial can be adapted for acne-prone or congestion-prone skin after your provider reviews your skin, sensitivities and current products.</p><p>Care may include gentle cleansing, appropriate exfoliation, a customized mask and hydration. Extractions are considered only when suitable for your skin and the appointment.</p><p>Looking for an anti-acne facial? Book a Custom Facial and share <strong>Clear + Balance</strong> as your skin goal. This is personalized cosmetic skincare; persistent, painful or scarring acne needs a dermatologist’s care.</p>'+link('EXPLORE CLEAR + BALANCE',WEB+'/facial-goals/clear-balance','text-link')+'</div></div></section>'
    menu=[('Custom Facial','60 OR 90 MINUTES · PRICE VARIES','Your starting point for hydration, acne-prone skin, congestion, sensitivity, uneven-looking texture or ongoing care. Book the time; we personalize the approach.','IUTRINR4YWTL7ULZ3QVEK4QG'),('New Client Facial with Lexy','45 MINUTES · $79','A welcoming first facial with a brief consultation and professional care selected for your skin. Available to guests new to Matrix facial services.','GJ7PY2ONLPOVK4JIYCIWJGG4'),('Circadia Dream Facial','90 MINUTES · $175','A restorative Circadia experience with intensive hydration and cooling professional care for a replenished, well-rested-looking finish.','5TMAAL7UNW75SMC6XG7R53QA'),('Circadia Luxe Lift Facial','75 MINUTES · $150','Raspberry Enzyme, a Firming Peptide Mask and targeted hydration for a smoother, brighter and firmer-looking complexion.','WBRKBJ3WLEKZEMRTZ52M26Q6'),('Dermaplane Refresh','30 MINUTES · $65','Focused professional dermaplaning with hydration and finishing care for surface texture and fine facial hair.',''),('Custom Dermaplane Facial','60 MINUTES · $135','Dermaplaning paired with a complete facial, masks, serums and finishing care selected around your skin.',''),('Luxe Dermaplane Facial','90 MINUTES · $185','An extended dermaplaning facial with more time for professional skincare, hydration and a polished finish.',''),('Facial &amp; Head/Scalp Massage','30 MINUTES + · PRICE VARIES','A massage-focused experience for the face, head and scalp with lightweight facial hydration. A different option from a full skincare facial.','')]
    b+='<section class="section" id="facial-menu"><div class="inner">'+intro('THE FACIAL MENU','Choose the experience that fits.','Begin with custom care or choose a specific treatment. The booking menu shows available providers, times and current pricing.')+'<div class="cards">'+''.join(card(t,m,d,BOOK+'/'+i if i else BOOK) for t,m,d,i in menu)+'</div><p class="note center">Dermaplaning is selected only when suitable. Tell your provider about active breakouts, irritated skin, retinoids and recent treatments before booking.</p></div></section>'
    goals=[('Hydrate + Restore','For dry or depleted skin that needs a softer, more comfortable feel.','hydrate-restore'),('Brighten + Smooth','For dull-looking skin and uneven-looking surface texture.','brighten-smooth'),('Clear + Balance','For acne-prone skin, congestion and excess shine, with comfort in view.','clear-balance'),('Calm + Support','For sensitive-feeling skin that calls for a gentler approach.','calm-support'),('Age-Defying + Firm','For a focus on firmness, radiance and smooth-looking texture.','age-defying-firm'),('Maintain + Glow','For regular care and a healthy-looking, refreshed complexion.','maintain-glow')]
    b+='<section class="section paper" id="skin-goals"><div class="inner">'+intro('EXPLORE BY SKIN GOAL','A clearer starting point.','These pathways help you describe what you want from your facial. Choose a service from the booking menu, then share the skin goal that fits.')+'<div class="goals">'+''.join(f'<article class="goal"><h3>{t}</h3><p>{d}</p>{link("EXPLORE THE PATHWAY",WEB+"/facial-goals/"+slug,"text-link")}</article>' for t,d,slug in goals)+'</div></div></section>'
    b+=faq([('Which facial should I choose for acne-prone skin?','Start with a Custom Facial and tell your provider that acne-prone skin or congestion is your priority. Clear + Balance is the related skin-goal pathway. Suitability and treatment steps are decided after reviewing your skin and routine.'),('Do you offer anti-acne facials?','Matrix offers personalized cosmetic facial care for acne-prone skin through the Custom Facial. Cleansing, suitable exfoliation, masks and hydration are selected for the individual. Facials do not replace medical acne treatment or guarantee clear skin.'),('Are extractions included in every facial?','No. Extractions are considered only when appropriate for your skin, comfort and booked appointment. Discuss congestion and active breakouts with your provider before treatment.'),('What should I share before my appointment?','Tell us about allergies, sensitivities, current skincare, prescription products, recent peels or waxing, and any active irritation. Follow your prescriber’s directions; ask about treatment timing if you are unsure.'),('Can I combine facial care with a Head Spa?','Yes. The current menu includes Matrix Head Spa + Hydrating Glow Facial, which pairs customized scalp care with a mini facial, facial massage and hydration. Review its current details when booking.'),('Where can I book a facial near Paddock Lake or Antioch?','Matrix Massage & Bodywork is at 24804 75th St, Salem, WI 53168. Our Salem studio welcomes clients from Salem Lakes, Paddock Lake, Bristol, Twin Lakes, Pleasant Prairie, Kenosha County and nearby Antioch, Illinois. Book online or text 262-939-9325.')])
    b+='<section class="section paper"><div class="inner">'+intro('MORE WAYS TO UNWIND','Make a little more room for care.','Explore scalp-focused relaxation or find practical information for visiting our Salem studio.')+'<div class="related">'+link('Japanese Head Spa',WEB+'/japanese-head-spa-salem-wi','')+link('Facials near Antioch',WEB+'/facials-near-antioch-il','')+link('Spa services near Paddock Lake',WEB+'/spa-services-near-paddock-lake-wi','')+'</div></div></section>'
    return b+closing('Thoughtful care for the skin you’re in.','From your first facial to your next skin goal, begin with a visit that feels personal.','BOOK A FACIAL')

def headspa():
    b=hero('head-spa','Japanese Head Spa in Salem, WI','Clean-feeling scalp. Warm water. Unhurried touch. A personalized scalp-care ritual with space to fully unwind.','head spa','Illustrative relaxing scalp massage at a black ceramic Head Spa basin.','45–120 minute experiences · Customized scalp care · Relaxation')
