def build():
    pages={'facials':('Custom Facials',facials,6),'head-spa':('Japanese Head Spa',headspa,8),'waxing':('Waxing & Hair Removal',waxing,8)}
    for key,(name,fn,count) in pages.items():
        p=BASE/key
        body=f'<div class="matrix-{key}">'+fn()+'</div>\n'
        css=CSS.replace('KEY',key).replace('WATER',WATER)
        (p/'body.html').write_text(body)
        (p/'style.css').write_text(css)
        baseline=json.loads((REVIEW/'baseline'/f'{key}.json').read_text())
        description=next(x['content'] for x in baseline['metadata'] if x.get('name')=='description')
        cfg=dict(serviceName=name,revision='review-1-2026-11-06',tagName=f'matrix-{key}-review',elementId={'facials':'matrixFacialReview','head-spa':'matrixHeadSpaReview','waxing':'matrixWaxingReview'}[key],rootClass=f'matrix-{key}',pageUrl=baseline['url'],seoTitle=baseline['title'],seoDescription=description,seoSource='../subpage-review-2026-11-06/baseline/'+key+'.json',bodyFile='body.html',cssFile='style.css',expectedFaqCount=count)
        (p/'page-config.json').write_text(json.dumps(cfg,indent=2)+'\n')
        subprocess.run(['python',str(ROOT/'plugins/matrix-page-builder/skills/matrix-page-workflow/scripts/build_page.py'),'--config',str(p/'page-config.json'),'--out',str(p/'review-1')],check=True)
    print('Three complete page bodies built; nothing installed or published.')

if __name__=='__main__':build()
